/**
 * @ohos/dsh-tool-html — a component kit, not a blank page.
 *
 * Writing an artifact page from scratch every time is wasted reasoning: the
 * model re-derives the same decisions (typography, spacing, dark mode, mobile
 * width, cards, tables, steps) and still ends up with two pages that look like
 * they came from two products. Worse, the choices that fail on this platform
 * are invisible from the code: a CDN font needs the network, a 打印 button does
 * nothing inside an embedded Web view, a missing viewport renders the page at
 * desktop width on a phone.
 *
 * So this tool ships the design once, as a small component kit:
 *
 *   - one inline stylesheet with tokens and ~16 components (hero, cards, grid,
 *     stats, steps, checklist, table, callouts, badges, bars, comparison,
 *     timeline, folds, key-values, quote, code);
 *   - `components` returns the catalogue — what each component is for and the
 *     exact snippet to paste — so composing a page is selection, not design;
 *   - `create` writes the skeleton with that stylesheet already inlined,
 *     light+dark, mobile-first, no network references and no page-level
 *     buttons (export/share belong to the shell);
 *   - `fill` places snippets into the page's content slot;
 *   - `check` reports what would break it on the device.
 *
 * Everything it writes stays inside the session workspace, so the
 * `workspace-write` sandbox keeps its meaning.
 */
import z from "@deepseek-ai/schemastery";
import { defineTool } from "@deepseek-ai/dsh-tools";
import { HarnessError } from "@deepseek-ai/dsh-llm";
import { existsSync, readFileSync } from "node:fs";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, isAbsolute, join, resolve } from "node:path";

const name = "tool-html";
const inject = [
	"tools",
	"workingDirectory"
];

const DEFAULT_MAX_KB = 2048;
const CONTENT_MARKER = "<!-- dsh:content -->";
/** End of the content slot: append inserts before it, so sections stay in <main>. */
const SLOT_END_MARKER = "<!-- dsh:content:end -->";
const END_MARKER = "<!-- dsh:end -->";
const PAGE_EXTENSIONS = [".html", ".htm"];

const Config = z.object({
	/** Ceiling for a page this tool will write or accept in `check`. */
	maxKb: z.number().default(DEFAULT_MAX_KB),
	/** Accent used when the caller does not pass one. */
	accent: z.string().default("#4d6bfe")
});

class HtmlError extends HarnessError {
	constructor(message, code) {
		super(message);
		this.name = "HtmlError";
		this.code = code;
	}
}

/* ------------------------------------------------------------------ paths */

/** A page path must stay inside the workspace and end in .html/.htm. */
function resolvePagePath(workdir, raw) {
	const trimmed = String(raw === undefined ? "" : raw).trim();
	if (trimmed.length === 0) {
		throw new HtmlError("path is required", "HTML_BAD_PATH");
	}
	const normalized = trimmed.replace(/\\/g, "/").replace(/^\.\//, "");
	if (isAbsolute(normalized) || normalized.split("/").includes("..")) {
		throw new HtmlError(`path must be relative to the workspace: ${trimmed}`, "HTML_BAD_PATH");
	}
	if (!PAGE_EXTENSIONS.some((ext) => normalized.toLowerCase().endsWith(ext))) {
		throw new HtmlError(`path must end in .html or .htm: ${trimmed}`, "HTML_BAD_PATH");
	}
	const root = resolve(workdir);
	const absolute = resolve(join(root, normalized));
	if (absolute !== root && !absolute.startsWith(`${root}/`)) {
		throw new HtmlError(`path escapes the workspace: ${trimmed}`, "HTML_BAD_PATH");
	}
	return { absolute, relative: normalized };
}

function escapeHtml(text) {
	return String(text)
		.replace(/&/g, "&amp;")
		.replace(/</g, "&lt;")
		.replace(/>/g, "&gt;")
		.replace(/"/g, "&quot;");
}

/* ---------------------------------------------------------------- stylesheet */

/**
 * The whole visual language in one block.
 *
 * Tokens first (`--bg`/`--text`/`--accent`…), then typography, then one class
 * family per component. Every component is pure HTML+CSS: no JavaScript, so an
 * exported long image or PDF cannot lose behaviour, and the page stays readable
 * in any viewer.
 */
const BASE_CSS = `:root {
  color-scheme: light dark;
  /* surfaces & text */
  --bg: #f7f7f5;
  --surface: #ffffff;
  --surface-2: #f0efea;
  --text: #1b1b19;
  --muted: #6b6b66;
  --line: #e4e2dc;
  /* semantic */
  --accent: __ACCENT__;
  --ok: #2f9e6f;
  --warn: #d9822b;
  --danger: #cf4436;
  /* chart palette: pages may override these per page */
  --c1: var(--accent);
  --c2: #7c6cf0;
  --c3: #2f9e6f;
  --c4: #d9822b;
  --c5: #cf4436;
  /* geometry & type: overridable, never baked into a component */
  --radius: 14px;
  --radius-sm: 10px;
  --radius-lg: 20px;
  --gap: 18px;
  --gap-sm: 10px;
  --gap-lg: 28px;
  --page-max: 760px;
  --line-height: 1.7;
  --fs-h1: 30px;
  --fs-h2: 20px;
  --fs-body: 16px;
  --fs-small: 12.5px;
  --font-body: -apple-system, "HarmonyOS Sans SC", "PingFang SC", "Noto Sans CJK SC", system-ui, sans-serif;
}
@media (prefers-color-scheme: dark) {
  html:not([data-theme="light"]) {
    --bg: #14140f;
    --surface: #1d1d17;
    --surface-2: #26261f;
    --text: #f2f1ea;
    --muted: #a3a29a;
    --line: #33332b;
    --ok: #4bbd8b;
    --warn: #e7a04c;
    --danger: #e8705f;
  }
}
html[data-theme="dark"] {
  color-scheme: dark;
  --bg: #14140f;
  --surface: #1d1d17;
  --surface-2: #26261f;
  --text: #f2f1ea;
  --muted: #a3a29a;
  --line: #33332b;
  --ok: #4bbd8b;
  --warn: #e7a04c;
  --danger: #e8705f;
}
html[data-theme="light"] { color-scheme: light; }
body.density-compact { --gap: 12px; --gap-sm: 7px; --gap-lg: 18px; --fs-body: 15px; --line-height: 1.6; }
body.density-roomy { --gap: 24px; --gap-lg: 40px; }
* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-body);
  line-height: var(--line-height);
  font-size: var(--fs-body);
}
.wrap { max-width: var(--page-max); margin: 0 auto; padding: 28px 18px 56px; }
.wrap.narrow { --page-max: 620px; }
.wrap.wide { --page-max: 980px; }
header.page { margin-bottom: var(--gap-lg); }
.eyebrow {
  font-size: var(--fs-small); letter-spacing: .12em; text-transform: uppercase;
  color: var(--muted); margin: 0 0 8px;
}
h1 { font-size: var(--fs-h1); line-height: 1.25; margin: 0 0 10px; letter-spacing: -.01em; }
h2 { font-size: var(--fs-h2); line-height: 1.35; margin: var(--gap-lg) 0 10px; }
h3 { font-size: calc(var(--fs-body) + 0.5px); margin: 22px 0 8px; }
p, li { font-size: var(--fs-body); }
p { margin: 0 0 14px; }
ul, ol { margin: 0 0 16px; padding-left: 22px; }
li { margin: 4px 0; }
a { color: var(--accent); text-decoration: none; border-bottom: 1px solid color-mix(in srgb, var(--accent) 40%, transparent); }
.lede { font-size: calc(var(--fs-body) + 1px); color: var(--muted); margin: 0 0 16px; }
small.muted { color: var(--muted); font-size: var(--fs-small); }

/* utility: spacing / colour / layout */
.mt-0 { margin-top: 0; } .mb-0 { margin-bottom: 0; }
.mt-sm { margin-top: var(--gap-sm); } .mb-sm { margin-bottom: var(--gap-sm); }
.mt-lg { margin-top: var(--gap-lg); } .mb-lg { margin-bottom: var(--gap-lg); }
.text-muted { color: var(--muted); }
.text-accent { color: var(--accent); }
.text-ok { color: var(--ok); }
.text-warn { color: var(--warn); }
.text-danger { color: var(--danger); }
.center { text-align: center; }
.row { display: flex; gap: var(--gap-sm); flex-wrap: wrap; align-items: center; }
.row.between { justify-content: space-between; }
.row.end { justify-content: flex-end; }

/* card / grid ------------------------------------------------------------ */
.card {
  background: var(--surface); border: 1px solid var(--line);
  border-radius: var(--radius); padding: 18px 18px 4px; margin: 0 0 var(--gap);
}
.card > h3:first-child { margin-top: 0; }
.card.flat { border-color: transparent; background: var(--surface-2); }
.card.tinted {
  background: color-mix(in srgb, var(--accent) 8%, var(--surface));
  border-color: color-mix(in srgb, var(--accent) 24%, var(--line));
}
.card.accent { background: var(--accent); border-color: var(--accent); color: #fff; }
.card.accent .card-foot, .card.accent h3 { color: #fff; }
.card-foot { color: var(--muted); font-size: var(--fs-small); padding: 10px 0 12px; }
.grid { display: grid; gap: var(--gap-sm); margin: 0 0 var(--gap); }
.grid-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.grid-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.grid-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
@media (max-width: 560px) {
  .grid-2, .grid-3, .grid-4 { grid-template-columns: minmax(0, 1fr); }
}

/* stats ------------------------------------------------------------------ */
.stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: var(--gap-sm); margin: 0 0 var(--gap); }
.stat { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 14px; }
.stat-value { font-size: 26px; font-weight: 700; line-height: 1.1; letter-spacing: -.02em; }
.stat.hero .stat-value { font-size: 46px; color: var(--accent); }
.stat-label { color: var(--muted); font-size: var(--fs-small); margin-top: 4px; }

/* steps / timeline ------------------------------------------------------- */
.steps { list-style: none; margin: 0 0 var(--gap); padding: 0; }
.step { display: flex; gap: 12px; padding: 0 0 16px; }
.step-num {
  flex: 0 0 26px; height: 26px; border-radius: 50%;
  background: color-mix(in srgb, var(--accent) 16%, transparent);
  color: var(--accent); font-size: 13px; font-weight: 700;
  display: flex; align-items: center; justify-content: center;
}
.step-body { flex: 1; }
.step-body strong { display: block; }
.steps.compact .step { padding-bottom: 8px; }
.timeline { list-style: none; margin: 0 0 var(--gap); padding: 0 0 0 14px; border-left: 2px solid var(--line); }
.tl-item { position: relative; padding: 0 0 16px 14px; }
.tl-item::before {
  content: ""; position: absolute; left: -21px; top: 7px;
  width: 8px; height: 8px; border-radius: 50%; background: var(--accent);
}
.tl-when { color: var(--muted); font-size: var(--fs-small); letter-spacing: .02em; }
.tl-what { font-size: calc(var(--fs-body) - 1px); }

/* checklist -------------------------------------------------------------- */
.checklist { list-style: none; margin: 0 0 var(--gap); padding: 0; }
.checklist li { display: flex; gap: 10px; align-items: flex-start; padding: 7px 0; border-bottom: 1px dashed var(--line); }
.checklist li:last-child { border-bottom: 0; }
.checklist input { margin-top: 5px; accent-color: var(--accent); }

/* table ------------------------------------------------------------------ */
.table { width: 100%; overflow-x: auto; margin: 0 0 var(--gap); }
table { width: 100%; border-collapse: collapse; font-size: calc(var(--fs-body) - 1.5px); }
th, td { text-align: left; padding: 9px 10px; border-bottom: 1px solid var(--line); vertical-align: top; }
th { color: var(--muted); font-weight: 600; white-space: nowrap; }
table.compact th, table.compact td { padding: 5px 8px; }
tr.hi td { background: color-mix(in srgb, var(--accent) 7%, transparent); }

/* callout ---------------------------------------------------------------- */
.callout {
  display: flex; gap: 10px; padding: 12px 14px; border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--accent) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--accent) 26%, transparent);
  margin: 0 0 var(--gap); font-size: calc(var(--fs-body) - 1.5px);
}
.callout::before { content: "提示"; color: var(--accent); font-weight: 700; font-size: var(--fs-small); letter-spacing: .08em; padding-top: 2px; }
.callout-warn { background: color-mix(in srgb, var(--warn) 12%, transparent); border-color: color-mix(in srgb, var(--warn) 30%, transparent); }
.callout-warn::before { content: "注意"; color: var(--warn); }

/* badges / bars ---------------------------------------------------------- */
.badges { display: flex; flex-wrap: wrap; gap: 8px; margin: 0 0 var(--gap); }
.badge {
  font-size: var(--fs-small); padding: 3px 10px; border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 12%, transparent); color: var(--accent);
}
.badge.ok { background: color-mix(in srgb, var(--ok) 14%, transparent); color: var(--ok); }
.badge.warn { background: color-mix(in srgb, var(--warn) 14%, transparent); color: var(--warn); }
.bar { height: 8px; border-radius: 999px; background: var(--line); overflow: hidden; margin: 6px 0 4px; }
.bar-fill { height: 100%; background: var(--accent); border-radius: 999px; }
.bar-label { display: flex; justify-content: space-between; font-size: 13px; color: var(--muted); }

/* comparison ------------------------------------------------------------- */
.compare { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; margin: 0 0 var(--gap); }
@media (max-width: 560px) { .compare { grid-template-columns: minmax(0, 1fr); } }
.compare-col { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 14px; }
.compare-head { font-weight: 700; margin: 0 0 8px; }

/* key-values / folds / quote / code -------------------------------------- */
.kv { margin: 0 0 var(--gap); }
.kv-row { display: flex; gap: 12px; padding: 8px 0; border-bottom: 1px solid var(--line); }
.kv-row:last-child { border-bottom: 0; }
.kv-key { flex: 0 0 34%; color: var(--muted); font-size: 13.5px; }
.kv-val { flex: 1; font-size: calc(var(--fs-body) - 1.5px); }
details.fold { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius-sm); padding: 10px 14px; margin: 0 0 12px; }
details.fold summary { cursor: pointer; font-weight: 600; font-size: calc(var(--fs-body) - 1.5px); }
details.fold p:last-child { margin-bottom: 8px; }
blockquote { margin: 0 0 var(--gap); padding: 2px 0 2px 14px; border-left: 3px solid var(--accent); color: var(--muted); }
code, pre { font-family: "SF Mono", "HarmonyOS Sans Mono", ui-monospace, monospace; font-size: 13.5px; }
code { background: color-mix(in srgb, var(--muted) 14%, transparent); padding: 1px 5px; border-radius: 6px; }
pre { background: var(--surface); border: 1px solid var(--line); border-radius: 12px; padding: 14px; overflow-x: auto; }
pre code { background: none; padding: 0; }
hr { border: 0; border-top: 1px solid var(--line); margin: var(--gap-lg) 0; }
footer.page { margin-top: var(--gap-lg); color: var(--muted); font-size: var(--fs-small); }

/* charts (pure CSS / static SVG) ----------------------------------------- */
.chart-bars {
  display: flex; align-items: flex-end; gap: 10px; height: 170px;
  margin: 0 0 var(--gap); padding: 10px 2px 0; border-bottom: 1px solid var(--line);
}
.chart-col { flex: 1; display: flex; flex-direction: column; justify-content: flex-end; align-items: center; gap: 6px; height: 100%; }
.chart-bar { width: 100%; max-width: 46px; border-radius: 8px 8px 0 0; background: var(--c1); min-height: 3px; }
.chart-bar.alt { background: color-mix(in srgb, var(--c1) 42%, transparent); }
.chart-val { font-size: 11.5px; font-weight: 700; letter-spacing: -.01em; }
.chart-x { font-size: 11px; color: var(--muted); white-space: nowrap; }
.stack { display: flex; align-items: flex-end; gap: 10px; height: 180px; margin: 0 0 var(--gap); padding: 10px 2px 0; border-bottom: 1px solid var(--line); }
.stack-col { flex: 1; display: flex; flex-direction: column-reverse; justify-content: flex-start; gap: 2px; height: 100%; }
.stack-seg { width: 100%; border-radius: 4px; min-height: 3px; background: var(--c1); }
.stack-seg.c2 { background: var(--c2); } .stack-seg.c3 { background: var(--c3); } .stack-seg.c4 { background: var(--c4); } .stack-seg.c5 { background: var(--c5); }
.stack-col .chart-x { text-align: center; display: block; }
.hbars { margin: 0 0 var(--gap); }
.hbar { display: grid; grid-template-columns: minmax(72px, 34%) 1fr auto; gap: 10px; align-items: center; padding: 5px 0; font-size: calc(var(--fs-body) - 1.5px); }
.hbar-label { color: var(--muted); }
.hbar-track { height: 10px; background: var(--surface-2); border-radius: 999px; overflow: hidden; }
.hbar-fill { height: 100%; background: var(--c1); border-radius: 999px; }
.hbar-val { font-size: var(--fs-small); font-weight: 700; min-width: 34px; text-align: right; }
svg.chart-line { width: 100%; height: auto; margin: 0 0 var(--gap); }
svg.chart-line .axis { stroke: var(--line); stroke-width: 1; }
svg.chart-line .grid-line { stroke: var(--line); stroke-width: 1; stroke-dasharray: 3 3; opacity: .6; }
svg.chart-line .series { fill: none; stroke: var(--c1); stroke-width: 2.5; stroke-linejoin: round; stroke-linecap: round; }
svg.chart-line .series-2 { fill: none; stroke: var(--c2); stroke-width: 2.5; stroke-dasharray: 5 4; }
svg.chart-line .area { fill: color-mix(in srgb, var(--c1) 16%, transparent); stroke: none; }
svg.chart-line .tick { fill: var(--muted); font-size: 11px; }
.legend { display: flex; gap: 14px; flex-wrap: wrap; font-size: var(--fs-small); color: var(--muted); margin: -6px 0 var(--gap); }
.legend i { display: inline-block; width: 10px; height: 10px; border-radius: 3px; background: var(--c1); margin-right: 6px; vertical-align: -1px; }
.legend i.c2 { background: var(--c2); } .legend i.c3 { background: var(--c3); } .legend i.c4 { background: var(--c4); } .legend i.c5 { background: var(--c5); }
.chart-donut { display: flex; align-items: center; gap: 16px; margin: 0 0 var(--gap); }
.donut {
  --p: 60%; flex: 0 0 auto; width: 118px; height: 118px; border-radius: 50%;
  background: conic-gradient(var(--c1) var(--p), var(--line) 0);
  display: grid; place-items: center;
}
.donut-hole {
  width: 78px; height: 78px; border-radius: 50%; background: var(--bg);
  display: grid; place-items: center; font-size: 20px; font-weight: 700; letter-spacing: -.02em;
}
.chart-legend { font-size: calc(var(--fs-body) - 4px); color: var(--muted); }
.chart-legend b { display: block; color: var(--text); font-size: 16px; margin: 2px 0; }
.section-head { margin: var(--gap-lg) 0 var(--gap-sm); }
.section-head h2 { margin: 0 0 6px; }
.section-head p { margin: 0; }
.heat { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 4px; margin: 0 0 var(--gap); }
.heat-cell { aspect-ratio: 1; border-radius: 5px; background: var(--surface-2); }
.heat-cell.l1 { background: color-mix(in srgb, var(--c1) 20%, var(--surface-2)); }
.heat-cell.l2 { background: color-mix(in srgb, var(--c1) 40%, var(--surface-2)); }
.heat-cell.l3 { background: color-mix(in srgb, var(--c1) 60%, var(--surface-2)); }
.heat-cell.l4 { background: color-mix(in srgb, var(--c1) 80%, var(--surface-2)); }
.heat-cell.l5 { background: var(--c1); }

/* media / people / plans ------------------------------------------------- */
.figure { margin: 0 0 var(--gap); }
.figure img, .figure svg { display: block; width: 100%; height: auto; border-radius: var(--radius); }
.figure .frame { border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; background: var(--surface-2); }
.figure .frame.ratio { aspect-ratio: 16 / 9; }
.figure-cap { color: var(--muted); font-size: var(--fs-small); margin-top: 6px; }
.gallery { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: var(--gap-sm); margin: 0 0 var(--gap); }
.gallery img, .gallery .frame { width: 100%; border-radius: var(--radius-sm); display: block; }
.avatars { display: flex; flex-direction: column; gap: var(--gap-sm); margin: 0 0 var(--gap); }
.avatar-row { display: flex; gap: 12px; align-items: flex-start; }
.avatar {
  flex: 0 0 38px; width: 38px; height: 38px; border-radius: 50%;
  background: color-mix(in srgb, var(--accent) 16%, transparent); color: var(--accent);
  display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 14px;
}
.avatar-body { flex: 1; }
.avatar-name { font-weight: 600; font-size: calc(var(--fs-body) - 1.5px); }
.avatar-meta { color: var(--muted); font-size: var(--fs-small); }
.plans { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: var(--gap-sm); margin: 0 0 var(--gap); }
.plan { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 16px; }
.plan.featured { border-color: var(--accent); box-shadow: 0 2px 0 var(--accent); }
.plan-name { color: var(--muted); font-size: var(--fs-small); letter-spacing: .04em; }
.plan-price { font-size: 28px; font-weight: 700; letter-spacing: -.02em; margin: 4px 0 10px; }
.plan ul { margin: 0; padding-left: 18px; }
.plan li { font-size: calc(var(--fs-body) - 1.5px); color: var(--muted); }

/* sortable / paged table ------------------------------------------------ */
th.sortable { cursor: pointer; user-select: none; }
th.sortable::after { content: "\\2195"; opacity: .35; margin-left: 6px; font-size: 11px; }
th.sortable[aria-sort="ascending"]::after { content: "\\2191"; opacity: 1; color: var(--accent); }
th.sortable[aria-sort="descending"]::after { content: "\\2193"; opacity: 1; color: var(--accent); }
.table-pager {
  display: flex; gap: 10px; align-items: center; justify-content: flex-end;
  font-size: var(--fs-small); color: var(--muted); margin: -8px 0 var(--gap);
}
.table-pager button {
  font: inherit; color: var(--text); background: var(--surface);
  border: 1px solid var(--line); border-radius: 999px; padding: 4px 12px; cursor: pointer;
}
.table-pager button[disabled] { opacity: .4; cursor: default; }

@media print {
  body { background: #fff; color: #000; }
  .card, .stat, .compare-col, .plan { border-color: #ccc; break-inside: avoid; }
  a { border-bottom: 0; }
  .table-pager { display: none; }
}`;

/* --------------------------------------------------------------- component kit */

/**
 * The catalogue the model composes from.
 *
 * `snippet` is deliberately copy-pasteable with placeholder text: the point is
 * that the shape is decided here, once, and the model only fills meaning in.
 * `classes` lets the tests prove every snippet's classes exist in BASE_CSS.
 */
